// ReleaseSubmission What the database project's CI hands over. Everything here is the output
// of a pipeline step Avior did not run and cannot repeat, which is why it
// is submitted rather than derived.
type ReleaseSubmission struct {
	Author    string `json:"author"`
	CommitSha string `json:"commitSha"`

	// Database The target database on the governed server.
	Database string `json:"database"`

	// ExpectedSchemaDigest The digest the target is expected to hold *before* this migration —
	// computed by CI over the database it built by replaying the migration
	// history. Avior computes the target's real digest and refuses when the
	// two disagree, because that means production moved by hand.
	//
	// `avior:empty-schema` where the target is expected to hold nothing,
	// which is what a baseline says: the database was created and nothing
	// has been applied to it. It is a phrase rather than a hash so it
	// cannot collide with one, and CI produces it from the same
	// `cmd/schemadigest` Avior compares with — so a baseline lands on an
	// empty database and is refused by a populated one, and a migration
	// carrying a hash is refused by an empty one.
	ExpectedSchemaDigest string         `json:"expectedSchemaDigest"`
	LintFindings         *[]LintFinding `json:"lintFindings,omitempty"`
	MergeRequestUrl      *string        `json:"mergeRequestUrl,omitempty"`

	// Migrations In the order they must be applied.
	Migrations      []MigrationFile `json:"migrations"`
	StagingSyncedAt *time.Time      `json:"stagingSyncedAt,omitempty"`

	// VerifyResult Step 3 of the pipeline: a fresh database replayed to production's
	// revision, the migration applied, the result asserted equal to the
	// declarative schema files.
	VerifyResult *struct {
		AgainstProductionRestore *bool   `json:"againstProductionRestore,omitempty"`
		Detail                   *string `json:"detail,omitempty"`
		Passed                   *bool   `json:"passed,omitempty"`
	} `json:"verifyResult,omitempty"`
}

